 24	@Service
 25	@RequiredArgsConstructor
 26	@Slf4j
 27	public class OrderBidCommandService {
 28	
 29	    private final OrderBidRepository orderBidRepository;
 30	    private final OrderCommandService orderCommandService;
 31	    private final ProductSizeQueryService productSizeQueryService;
 32	    private final UserQueryService userQueryService;
 33	    private final SaleBidQueryService saleBidQueryService;
